contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address to, uint256 value) public {
        require(to != address(0));
        require(value <= c.balanceOf(address(this)));
        uint256 totalBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;
        bool ok = c.transfer(to, value); if (__ESBMC_reverted()) return;
        assert(
            ok &&
            c.balanceOf(address(this)) == balBefore - value &&
            c.balanceOf(to) == toBefore + value &&
            c.totalSupply() == totalBefore
        );
    }
    receive() external payable {}
}

